"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63289"],{63823(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.fato_resolvido_em_fase_posterior","status":422,"titulo":"O documento \xe9 exigido por um fato que s\xf3 se conhece numa fase posterior"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.fato_resolvido_em_fase_posterior","requisitos":[],"oQueAconteceu":["Nenhum documento \xe9 pedido antes de o fato de que ele depende ser conhecido. A exig\xeancia\\ndepende de um fato que s\xf3 passa a ser conhecido numa fase com ordem posterior \xe0 da fase em que\\no documento \xe9 exigido. O fato pode vir da condi\xe7\xe3o do documento ou de um campo do grupo\\nrepet\xedvel pelo qual a exig\xeancia se repete; no segundo caso, a condi\xe7\xe3o do documento n\xe3o \xe9 a\\ncausa. A mensagem de detalhe nomeia o fato e a fase dele, com a ordem de cada fase.","O fato \xe9 conhecido na mais tardia entre: a fase em que o cat\xe1logo de fatos o situa, a fase do\\nformul\xe1rio que o coleta e, para o fato derivado por regra, as fases dos fatos de que ele\\ndepende. Para o campo de grupo repet\xedvel, vale a fase do formul\xe1rio que coleta o grupo.","A ordem das fases \xe9 a **ordem derivada do cronograma**: a posi\xe7\xe3o de cada fase na\\nlista, somada \xe0 escolha \\"no mesmo momento da anterior\\" (UNI-REQ-0485), que faz duas\\nfases ocuparem o mesmo momento. Uma fase que acontece no mesmo momento da fase da\\nexig\xeancia n\xe3o \xe9 posterior a ela, ent\xe3o n\xe3o causa esta recusa. Por isso, o pedido de\\nisen\xe7\xe3o ordenado antes da inscri\xe7\xe3o s\xf3 pode exigir documento por um fato coletado\\nna inscri\xe7\xe3o se o edital deixar as duas no mesmo momento: a inscri\xe7\xe3o, e cada fase\\nque ficar entre ela e a isen\xe7\xe3o, precisam estar marcadas com \\"no mesmo momento da\\nanterior\\". Sem isso, a inscri\xe7\xe3o vem depois e a recusa sai. A mensagem da resposta diz: \\"O fato \'*c\xf3digo do fato*\' s\xf3 \xe9 conhecido na fase \'*c\xf3digo da\\nfase*\' (ordem N), posterior \xe0 fase em que o documento \xe9 exigido (ordem M).\\" Vale na grava\xe7\xe3o,\\nna publica\xe7\xe3o e na retifica\xe7\xe3o.","A confer\xeancia acontece na defini\xe7\xe3o dos documentos exigidos, na aplica\xe7\xe3o de um modelo de\\nformul\xe1rio e, com o cat\xe1logo de fatos, na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico. Ela vem depois de\\n[`ponto_resolucao_fora_do_cronograma`](/erros/uniplus.selecao.documento_exigido.ponto_resolucao_fora_do_cronograma)\\ne antes de\\n[`fato_de_formulario_nao_alcancado`](/erros/uniplus.selecao.documento_exigido.fato_de_formulario_nao_alcancado)."],"comoResolver":["Conforme a origem do fato:","- se ele est\xe1 numa condi\xe7\xe3o do documento, passe a exig\xeancia para uma fase em que o fato j\xe1 seja\\n  conhecido, ou troque a condi\xe7\xe3o por um fato conhecido at\xe9 a fase do documento;\\n- se \xe9 de campo de um grupo repet\xedvel, trocar a condi\xe7\xe3o n\xe3o resolve: passe a exig\xeancia para\\n  uma fase em que o grupo j\xe1 seja conhecido, vincule-a a um grupo coletado at\xe9 a fase dela ou\\n  retire a repeti\xe7\xe3o por grupo."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Aplica\xe7\xe3o de modelo de formul\xe1rio","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);